// ii: target 是 var，JS 动态读 target.radius。Rectangle（及以它为根的组件）有 radius；
// 其他 Item（如 WallpaperDirectoryItem 的 Loader、TodoWidget 的 FloatingActionButton）没有，读到 undefined。
// RectangularShadow.radius 不可重置：绑定得到 undefined 时 QML 报 "Unable to assign [undefined] to double"
// 并保留原值（初始 0）。target 为 null 时 JS 抛 TypeError，同样保留原值；C++ 构造期 target 还没赋值时也走这里。
auto* targetRect = dynamic_cast<::ii::Rectangle*>(this->target.get());
if (targetRect == nullptr) {
  return this->radius.peek();
}
return targetRect->radius.get();
